-- PT103-S2-Q6. Batch 11.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch11$PT103-S2-Q6$batch11$ AND q.stimulus=$batch11$The largest volcano on Mars rises 27 kilometers above the surrounding plain and covers an area roughly the size of Romania. Even if the Earth’s gravity were as low as the gravity of Mars is, no volcano of such size could exist on Earth, for the Earth’s crust, although of essentially the same composition as that of Mars, is too thin to support even a small fraction of that mass and would buckle under it, causing the mountain to sink.$batch11$ AND q.prompt=$batch11$If the statements above are true, which one of the following must also be true on the basis of them?$batch11$ AND q.correct_choice=$batch11$D$batch11$) THEN RAISE EXCEPTION 'Question changed: PT103-S2-Q6'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch11$PT103-S2-Q6$batch11$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT103-S2-Q6'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch11$PT103-S2-Q6$batch11$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch11$Statements$batch11$, $batch11$The largest volcano on Mars is enormous. No volcano that size could exist on Earth, even with Mars's low gravity, because Earth's crust is too thin to hold that mass.$batch11$), (1, $batch11$Evaluate$batch11$, $batch11$Gravity is set aside on purpose ("even if"), and the crusts are the same material. The only difference left is thickness. Mars's crust does hold the volcano, so at least where the volcano sits, Mars's crust must be thicker than Earth's.$batch11$), (2, $batch11$Goal$batch11$, $batch11$Mars's crust is thicker than Earth's at some point.$batch11$)) v(position,label,body) WHERE q.qid=$batch11$PT103-S2-Q6$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch11$A$batch11$, $batch11$Erosion never comes up.$batch11$), ($batch11$B$batch11$, $batch11$We know the crust under this one volcano is thick enough. We know nothing about where the other high volcanoes sit or where the crust is thickest.$batch11$), ($batch11$C$batch11$, $batch11$We know about the largest volcano on each planet, not the average height of volcanoes.$batch11$), ($batch11$D$batch11$, $batch11$Same material, gravity set aside, and Mars holds a mass Earth's crust could not. Mars's crust must be thicker at least there.$batch11$), ($batch11$E$batch11$, $batch11$A thicker crust would let Earth support bigger volcanoes. That doesn't mean any real volcano would actually be bigger. Volcanoes need magma and eruptions too.$batch11$)) v(letter,body) WHERE q.qid=$batch11$PT103-S2-Q6$batch11$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
